package proto_test

import (
	"testing"

	protov1 "github.com/golang/protobuf/proto"
	"google.golang.org/grpc/encoding"
	_ "google.golang.org/grpc/encoding/proto"
)

// legacyMsg implements only the APIv1 message interface, like code generated
// by protoc-gen-go < v1.4 or gogo/protobuf.
type legacyMsg struct {
	Name string `protobuf:"bytes,1,opt,name=name,proto3" json:"name,omitempty"`
}

func (m *legacyMsg) Reset()         { *m = legacyMsg{} }
func (m *legacyMsg) String() string { return "legacy:" + m.Name }
func (*legacyMsg) ProtoMessage()    {}

func TestThermoLegacyCodec(t *testing.T) {
	c := encoding.GetCodec("proto")
	b, err := c.Marshal(&legacyMsg{Name: "hello"})
	t.Logf("Marshal: bytes=%v err=%v", b, err)
	if err != nil {
		t.Fatalf("Marshal of v1-only message failed: %v", err)
	}
	out := &legacyMsg{}
	if err := c.Unmarshal(b, out); err != nil {
		t.Fatalf("Unmarshal of v1-only message failed: %v", err)
	}
	if out.Name != "hello" {
		t.Fatalf("got %q", out.Name)
	}
	_ = protov1.Marshal
}
EOF
