package status_test

import (
	"testing"

	protov1 "github.com/golang/protobuf/proto"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

type legacyDetail struct {
	Name string `protobuf:"bytes,1,opt,name=name,proto3" json:"name,omitempty"`
}

func (m *legacyDetail) Reset()         { *m = legacyDetail{} }
func (m *legacyDetail) String() string { return "legacy:" + m.Name }
func (*legacyDetail) ProtoMessage()    {}

func init() { protov1.RegisterType((*legacyDetail)(nil), "grpc.thermo.LegacyDetail") }

func TestThermoLegacyDetails(t *testing.T) {
	s, err := status.New(codes.Internal, "x").WithDetails(&legacyDetail{Name: "hello"})
	if err != nil {
		t.Fatalf("WithDetails: %v", err)
	}
	d := s.Details()
	t.Logf("Details()[0] dynamic type = %T", d[0])
	if _, ok := d[0].(*legacyDetail); !ok {
		t.Errorf("Details()[0] is %T, want *legacyDetail", d[0])
	}
	if _, ok := d[0].(protov1.Message); !ok {
		t.Errorf("Details()[0] (%T) does not implement the v1 proto.Message interface", d[0])
	}
}
EOF
